-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["7114ab5089f7cdbf"] = { "Inutile dire che noi, la guarnigione di Kargath, siamo molto soddisfatti del nostro incarico. Qui restiamo duri, perché se ci rammolliamo moriamo.\n\nE non vorrei che fosse altrimenti.\n\nNeeka Bloodscar\nCapo esploratrice, Kargath", "." },
  ["711ab8e1c07f2225"] = { "Negli anni che seguirono, dopo che ⟦Stormwind=Roccavento⟧ ebbe tradito la Stonemasons' Guild, Sir Erlgadin divenne amareggiato riguardo al ruolo dei nobili nel Regno. Non desiderava più mantenere la posizione che la stirpe di suo padre gli aveva guadagnato nella House of Nobles.\n\nMa sto divagando. Lo scopo di questo racconto non è fare da trattato politico né da biografia. Questo è il resoconto delle mie esperienze di caccia grossa sulle verdi colline di Rovotorto....", "." },
  ["712343b0a36c48a1"] = { "La guerra infuriò sui continenti di Khaz Modan, di Lordaeron e della stessa Azeroth. Nel corso della sua campagna settentrionale, l'⟦Horde=Orda⟧ riuscì a dare alle fiamme le terre di confine di Quel'Thalas, assicurando così l'impegno definitivo degli elfi nella causa dell'Alleanza. Le città e i borghi più grandi di Lordaeron furono rasi al suolo e devastati dal conflitto. Nonostante l'assenza di rinforzi e un nemico soverchiante, Lothar e i suoi alleati riuscirono a tenere a bada gli avversari.", "." },
  ["71479c7efa3ab91b"] = { "Questo buono vale un pezzo di armatura di cuoio o di stoffa, da ritirare presso la famiglia Timberlain al ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧.", "." },
  ["7166ce29e3db1085"] = { "Minerale raffinato - A Thelsamar c'è un nano, un fabbro con cui mi sono addestrato per un po' di tempo, di nome Bailor Stonehand. Produce una lega molto speciale che credo sarebbe perfetta per la tua arma. Aspettavo che mi arrivasse una spedizione di quella lega mentre ero a ⟦Ironforge=Forgiardente⟧, ma non ho ancora avuto sue notizie.\n\nTrovalo e informati sulla spedizione. E se non è più a Loch Modan, vorrei almeno sapere che cosa è successo al mio vecchio maestro.", "." },
  ["716e6a76c4f923d9"] = { "Devo supporre che lo scompiglio che questi spiriti provocano, attraverso canali sotto la guida degli sciamani e dei druidi tauren, li distragga. Perché i tauren considerano la ⟦Venture Company=S.P.R. & Co.⟧ sulle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧ una grave minaccia.\n\nMinaccia o no, dobbiamo aiutare i nostri alleati.\n\nLydon, hai una vasta conoscenza delle tossine. Puoi crearne una che potremmo usare per diffondere un contagio tra i goblin di ⟦Stonetalon=Petrartiglio⟧?\n\nCon i miei omaggi di studiosa, \nP. Zamah", "." },
  ["71ba17c63c56181b"] = { "Ajeck e Sir Erlgadin prepararono le armi, ai miei fianchi, le spalle rivolte al mare. Barnil emise un sospiro rassegnato ed estrasse l'ascia. I Lashtail erano quasi su di noi. La loro andatura costante aveva rallentato. Ora braccavano la preda, perché sapevano di averci in trappola.", "." },
  ["71dc229643105a98"] = { "Il nostro mondo trabocca di storia. Storia di razze nuove e antiche. Storia di guerre da tempo estinte e di altre che ancora covano sotto la cenere.\n\nStoria di dei giunti dai cieli. E storia di dei più antichi che dormono nella terra.\n\nParlo ora di quegli esseri: gli Dei Antichi. Coloro che dimorarono e infuriarono su Azeroth quando il mondo era giovane.", "." },
  ["71f88e19d13d4ae9"] = { "Ma aveva ragione. Siamo condannati. La stirpe degli Agamand si estinguerà. Anche se sono ancora vivo, so che presto sarò morto.\n\nNon ho paura, e non mi pento di essere rimasto con la mia famiglia. Ma i miei ultimi pensieri saranno per te.\n\nVivi, mia amata Yvette, e io troverò la pace,\n-Thurman", "." },
})
